UPDATE tools SET faq = $x$[{"q": "Qu'est-ce que Fiscal.ai / FinChat ?", "a": "Fiscal.ai (également connu sous le nom de FinChat) est un outil de recherche financière basé sur l'IA qui permet aux investisseurs de dialoguer avec les documents financiers d'une entreprise — transcriptions de conférences téléphoniques sur les résultats, documents déposés auprès de la SEC, rapports annuels. Posez n'importe quelle question et obtenez des réponses sourcées directement à partir des documents originaux."}, {"q": "Fiscal.ai peut-il analyser plusieurs entreprises à la fois ?", "a": "Fiscal.ai est surtout adapté à la recherche approfondie sur des entreprises spécifiques — en interrogeant leurs documents en détail. Pour comparer simultanément plusieurs entreprises selon des indicateurs quantitatifs, les outils de filtrage et de comparaison de Koyfin sont plus efficaces."}]$x$::jsonb
