UPDATE tools SET faq = $x$[{"q": "O que é Fiscal.ai / FinChat?", "a": "Fiscal.ai (também conhecido como FinChat) é uma ferramenta de pesquisa financeira com IA que permite aos investidores conversar com documentos financeiros de empresas — transcrições de teleconferências de resultados, documentos regulatórios (SEC), relatórios anuais. Basta fazer qualquer pergunta e obter respostas com citações diretamente das fontes originais."}, {"q": "O Fiscal.ai consegue analisar várias empresas ao mesmo tempo?", "a": "O Fiscal.ai é mais indicado para pesquisas aprofundadas sobre empresas específicas — consultando seus documentos em detalhe. Para comparar várias empresas simultaneamente com base em métricas quantitativas, as ferramentas de triagem e comparação do Koyfin são mais eficientes."}]$x$::jsonb
