UPDATE tools SET faq = $x$[{"q": "Was ist Khanmigo?", "a": "Khanmigo ist der KI-Tutor-Assistent von Khan Academy. Er läuft auf den Modellen von OpenAI über Microsofts Azure OpenAI Service, wobei Google Gemini einige neuere Funktionen wie interaktive Diagramme antreibt. Er hilft Schülern bei schulischen Fächern nach der sokratischen Methode — durch leitende Fragen statt direkter Antworten. Er ist für Lehrer kostenlos, aber der Zugang für einzelne Schüler und Familien erfordert ein kostenpflichtiges Abonnement."}, {"q": "Ist Khanmigo kostenlos?", "a": "Khanmigo ist für Lehrer kostenlos, ohne dass ein Abonnement erforderlich ist. Der Zugang für einzelne Schüler und für Familien kostet jeweils 4 $ pro Monat oder 44 $ pro Jahr, zuzüglich Umsatzsteuer. Manche Schulbezirke stellen ihren Schülern über Bezirksvereinbarungen mit Khan Academy kostenlosen Zugang zu Khanmigo bereit."}, {"q": "Kann Duolingo mir Fließend-Sprechen beibringen?", "a": "Duolingo baut effektiv Vokabular und grundlegende Grammatik auf, reicht aber im Allgemeinen nicht aus, um allein Fließend zu werden. Es funktioniert am besten als tägliche Gewohnheit in Kombination mit anderer Übung wie Gesprächen mit Muttersprachlern, dem Anschauen von Inhalten oder der Nutzung von Tools wie iTalki für Konversationsübungen."}]$x$::jsonb
 WHERE slug = 'khanmigo' AND lang = 'de';

