UPDATE tools SET faq = $x$[{"q": "Что такое Khanmigo?", "a": "Khanmigo — это ИИ-репетитор от Khan Academy. Он работает на моделях OpenAI через сервис Microsoft Azure OpenAI Service, а Google Gemini обеспечивает некоторые новые функции, такие как интерактивные диаграммы. Он помогает учащимся с академическими предметами, используя метод Сократа — задавая наводящие вопросы вместо прямых ответов. Он бесплатен для учителей, но индивидуальный доступ для учеников и семей требует платной подписки."}, {"q": "Является ли Khanmigo бесплатным?", "a": "Khanmigo бесплатен для учителей, подписка не требуется. Индивидуальный доступ для учеников и доступ для семей стоят по $4 в месяц или $44 в год, плюс налог с продаж. Некоторые школьные округа предоставляют бесплатный доступ ученикам к Khanmigo через соглашения на уровне округа с Khan Academy."}, {"q": "Может ли Duolingo научить меня свободно говорить на языке?", "a": "Duolingo эффективно формирует словарный запас и базовую грамматику, но, как правило, недостаточен для достижения свободного владения языком сам по себе. Лучше всего он работает как ежедневная привычка в сочетании с другой практикой, например общением с носителями языка, просмотром контента или использованием таких инструментов, как iTalki, для разговорной практики."}]$x$::jsonb
 WHERE slug = 'khanmigo' AND lang = 'ru';

