UPDATE tools SET faq = $x$[{"q": "O que é o Khanmigo?", "a": "Khanmigo é o assistente de tutoria com IA da Khan Academy. Ele roda sobre os modelos da OpenAI via Azure OpenAI Service da Microsoft, com o Google Gemini alimentando alguns recursos mais novos, como diagramas interativos. Ele ajuda estudantes em disciplinas acadêmicas usando o método socrático — fazendo perguntas orientadoras em vez de dar respostas diretas. É gratuito para professores, mas o acesso individual para estudantes e famílias exige assinatura paga."}, {"q": "O Khanmigo é gratuito?", "a": "O Khanmigo é gratuito para professores, sem necessidade de assinatura. O acesso individual para estudantes e o acesso familiar custam, cada um, US$ 4 por mês ou US$ 44 por ano, mais impostos sobre vendas. Algumas redes escolares oferecem acesso gratuito aos estudantes ao Khanmigo por meio de acordos em nível distrital com a Khan Academy."}, {"q": "O Duolingo pode me ensinar a ser fluente?", "a": "O Duolingo desenvolve vocabulário e gramática básica de forma eficaz, mas geralmente não é suficiente para alcançar fluência sozinho. Funciona melhor como um hábito diário combinado com outras práticas, como conversar com falantes nativos, assistir a conteúdos ou usar ferramentas como o iTalki para praticar conversação."}]$x$::jsonb
