UPDATE tools SET faq = $x$[{"q": "Qu'est-ce que Manus ?", "a": "Manus est un agent IA autonome capable d'accomplir de manière indépendante des tâches complexes — naviguer sur le web, écrire et exécuter du code, gérer des fichiers et remplir des formulaires — sans instructions pas à pas."}, {"q": "Combien coûte Manus ?", "a": "Manus propose des abonnements mensuels payants à partir de 20 $/mois, avec des paliers supérieurs à 40 $/mois et 200 $/mois selon les allocations de crédits, le nombre de tâches simultanées et de tâches planifiées. Des plans personnalisés Teams & Businesses sont également disponibles. Il n'existe pas de formule gratuite pour le produit principal listé sur sa page tarifaire."}, {"q": "Que peut faire Manus de manière autonome ?", "a": "Manus peut faire des recherches sur des sujets sur le web, écrire et exécuter du code, gérer des fichiers, remplir des formulaires, monter des vidéos, créer des jeux et déclencher automatiquement des tâches à partir d'événements dans les e-mails, le calendrier ou Slack — le tout à partir d'une seule instruction de haut niveau."}, {"q": "En quoi Manus diffère-t-il des autres agents IA ?", "a": "Manus fonctionne avec un environnement persistant semblable à un bureau — il peut ouvrir des navigateurs, exécuter des terminaux et gérer des fichiers comme un assistant humain. La plupart des agents IA ne font que générer du texte ; Manus exécute réellement des tâches dans un véritable environnement informatique."}]$x$::jsonb
