UPDATE tools SET faq = $x$[{"q": "O que é o Manus?", "a": "Manus é um agente de IA autônomo que pode concluir tarefas complexas de forma independente — navegando na web, escrevendo e executando código, gerenciando arquivos e preenchendo formulários — sem instruções passo a passo."}, {"q": "Quanto custa o Manus?", "a": "O Manus oferece planos mensais pagos a partir de US$ 20/mês, com níveis superiores de US$ 40/mês e US$ 200/mês, com base em alocações de créditos, tarefas simultâneas e tarefas agendadas. Planos personalizados Teams & Businesses também estão disponíveis. Não há um nível gratuito para o produto principal listado em sua página de preços."}, {"q": "O que o Manus pode fazer de forma autônoma?", "a": "O Manus pode pesquisar tópicos na web, escrever e executar código, gerenciar arquivos, preencher formulários, editar vídeos, criar jogos e acionar tarefas automaticamente a partir de eventos de e-mail, calendário ou Slack — tudo a partir de uma única instrução de alto nível."}, {"q": "Em que o Manus é diferente de outros agentes de IA?", "a": "O Manus opera com um ambiente persistente semelhante a um desktop — ele pode abrir navegadores, executar terminais e gerenciar arquivos como um assistente humano. A maioria dos agentes de IA apenas gera texto; o Manus realmente executa tarefas em um ambiente computacional real."}]$x$::jsonb
