UPDATE tools SET faq = $x$[{"q": "Was ist Relume?", "a": "Relume ist ein KI-Tool, das aus einer Textbeschreibung Website-Briefings, Sitemaps und Wireframes erstellt, mit einer Komponentenbibliothek für Webflow, Figma und React. Zudem gibt es eine in der Beta-Phase befindliche Publish-Funktion, die die fertige Website direkt auf einer eigenen Domain hosten kann, neben dem ursprünglichen Export-Workflow zu Webflow oder Figma."}, {"q": "Was ist der Unterschied zwischen Relume und Framer?", "a": "Die Kernstärke von Relume liegt in der KI-gestützten Planungsphase: Briefings, Sitemaps und Wireframes, plus eine große Komponentenbibliothek für Webflow, Figma und React. Der Export-Pfad übergibt die Weiterentwicklung an diese Plattformen. Relume verfügt nun auch über einen Publish-Pfad in Beta zum direkten Hosten einer Live-Website, wodurch sich der Abstand zu Tools wie Framer verringert, aber Publish ist neuer und weniger etabliert als Relumes Export-Workflow."}, {"q": "Ist Relume kostenlos?", "a": "Ja, beide Produkte von Relume verfügen über eine kostenlose Stufe. Der kostenlose Plan von Build with Relume erfordert keine Kreditkarte und beinhaltet begrenzte gemeinsam genutzte KI-Nutzung mit kostenlosem Hosting auf einer relume.live-Subdomain. Der kostenlose Plan von Site Builder umfasst 30 Webflow-Komponenten und 30 React-Komponenten. Kostenpflichtige Pläne beginnen bei 14 $/Monat für Build with Relume Pro und bei 18 $/Monat für Site Builder Starter."}, {"q": "Funktioniert Relume mit Figma?", "a": "Ja. Relumes Komponentenbibliothek und generierte Wireframes können nach Figma sowie nach Webflow und React (Tailwind CSS und shadcn/ui) exportiert werden, sodass Teams die Plattform wählen können, die zu ihrem Build-Prozess passt."}]$x$::jsonb
 WHERE slug = 'relume' AND lang = 'de';

