UPDATE tools SET faq = $x$[{"q": "Що таке Relume?", "a": "Relume — це ІІ-інструмент, який генерує брифи вебсайтів, карти сайту та wireframe-и на основі текстового опису, з бібліотекою компонентів для Webflow, Figma та React. Він також має бета-функцію Publish, яка може розмістити готовий сайт напряму на власному домені, поряд із початковим робочим процесом експорту у Webflow або Figma."}, {"q": "Яка різниця між Relume та Framer?", "a": "Основна сила Relume — це ІІ-керований етап планування: брифи, карти сайту та wireframe-и, а також велика бібліотека компонентів для Webflow, Figma та React. Його напрямок Export передає роботу цим платформам для фінального створення сайту. Тепер у Relume також є бета-напрямок Publish для прямого розміщення живого сайту, що скорочує розрив із такими інструментами, як Framer, але Publish новіший і менш усталений, ніж робочий процес експорту в Relume."}, {"q": "Чи безкоштовний Relume?", "a": "Так, обидва продукти Relume мають безкоштовний рівень. Безкоштовний план Build with Relume не потребує карти та включає обмежене спільне використання ІІ з безкоштовним хостингом на субдомені relume.live. Безкоштовний план Site Builder включає 30 компонентів Webflow та 30 компонентів React. Платні плани починаються від $14/місяць для Build with Relume Pro та від $18/місяць для Site Builder Starter."}, {"q": "Чи працює Relume з Figma?", "a": "Так. Бібліотеку компонентів Relume та згенеровані wireframe-и можна експортувати у Figma, а також у Webflow та React (Tailwind CSS та shadcn/ui), дозволяючи командам обирати платформу, яка відповідає їхньому процесу розробки."}]$x$::jsonb
 WHERE slug = 'relume' AND lang = 'ua';

