UPDATE tools SET faq = $x$[{"q": "Qu'est-ce que Relume ?", "a": "Relume est un outil d'IA qui génère des briefs de sites web, des sitemaps et des wireframes à partir d'une description textuelle, avec une bibliothèque de composants pour Webflow, Figma et React. Il dispose également d'une fonctionnalité de Publication en bêta permettant d'héberger le site terminé directement sur un domaine personnalisé, en plus du flux de travail original d'export vers Webflow ou Figma."}, {"q": "Quelle est la différence entre Relume et Framer ?", "a": "Le point fort principal de Relume réside dans l'étape de planification pilotée par l'IA : briefs, sitemaps et wireframes, ainsi qu'une vaste bibliothèque de composants pour Webflow, Figma et React. Son parcours Export transmet le projet à ces plateformes pour la construction finale. Relume dispose désormais aussi d'un parcours de Publication en bêta pour héberger un site en direct directement, ce qui réduit l'écart avec des outils comme Framer, mais Publish est plus récent et moins établi que le flux de travail d'export de Relume."}, {"q": "Relume est-il gratuit ?", "a": "Oui, les deux produits de Relume proposent un niveau gratuit. Le plan gratuit de Build with Relume ne nécessite aucune carte et inclut un usage IA partagé limité avec un hébergement gratuit sur un sous-domaine relume.live. Le plan gratuit de Site Builder inclut 30 composants Webflow et 30 composants React. Les plans payants commencent à 14 $/mois pour Build with Relume Pro et à 18 $/mois pour Site Builder Starter."}, {"q": "Relume fonctionne-t-il avec Figma ?", "a": "Oui. La bibliothèque de composants et les wireframes générés par Relume peuvent être exportés vers Figma, ainsi que vers Webflow et React (Tailwind CSS et shadcn/ui), permettant aux équipes de choisir la plateforme adaptée à leur processus de développement."}]$x$::jsonb
 WHERE slug = 'relume' AND lang = 'fr';

