UPDATE tools SET faq = $x$[{"q": "O que é o Relume?", "a": "Relume é uma ferramenta de IA que gera briefings, mapas de site e wireframes a partir de uma descrição em texto, com uma biblioteca de componentes para Webflow, Figma e React. Também possui um recurso de Publicação em beta que pode hospedar o site finalizado diretamente em um domínio personalizado, além do fluxo de trabalho original de exportação para Webflow ou Figma."}, {"q": "Qual é a diferença entre Relume e Framer?", "a": "O ponto forte principal do Relume é a etapa de planejamento orientada por IA: briefings, mapas de site e wireframes, além de uma grande biblioteca de componentes para Webflow, Figma e React. Seu caminho de Exportação repassa o trabalho para essas plataformas para a construção final. O Relume agora também tem um caminho de Publicação em beta para hospedar um site ao vivo diretamente, o que reduz a diferença em relação a ferramentas como o Framer, mas a Publicação é mais nova e menos consolidada do que o fluxo de exportação do Relume."}, {"q": "O Relume é gratuito?", "a": "Sim, ambos os produtos do Relume têm um nível gratuito. O plano gratuito do Build with Relume não exige cartão e inclui uso compartilhado de IA limitado com hospedagem gratuita em um subdomínio relume.live. O plano gratuito do Site Builder inclui 30 componentes Webflow e 30 componentes React. Os planos pagos começam em US$ 14/mês para o Build with Relume Pro e em US$ 18/mês para o Site Builder Starter."}, {"q": "O Relume funciona com o Figma?", "a": "Sim. A biblioteca de componentes e os wireframes gerados pelo Relume podem ser exportados para o Figma, bem como para Webflow e React (Tailwind CSS e shadcn/ui), permitindo que as equipes escolham a plataforma que melhor se encaixa em seu processo de construção."}]$x$::jsonb
 WHERE slug = 'relume' AND lang = 'pt';

UPDATE tools SET best_for = $x$AI-generated presentation templates for Google Slides and PowerPoint, with a limited free tier and paid Premium plans$x$
 WHERE slug = 'slidesgo' AND lang = 'en';

UPDATE tools SET description = $x$Slidesgo is an AI-powered presentation template platform with 30,000+ templates for Google Slides and PowerPoint. The free tier includes 3 AI-generated presentations and 3 template downloads per month; Premium unlocks the full library, with pricing that varies by region and billing cycle.$x$
 WHERE slug = 'slidesgo' AND lang = 'en';

UPDATE tools SET description_long = $x$Slidesgo is a presentation template platform with AI generation capabilities, offering more than 30,000 professionally designed templates for Google Slides and PowerPoint. Roughly 15,000 of those templates are exclusive to the paid Premium tier.

The product is actively maintained; the vendor does not publish a version number or disclose which AI model powers its generation feature, so neither can be confirmed here. No independently verified user-count figure was found on Slidesgo's own pages.

Slidesgo AI generates a complete presentation deck from a topic description, selecting templates and generating slide content. The library spans most common use cases — business reports, educational presentations, marketing decks, project proposals, event announcements — with new templates reportedly added on a regular basis.

Pricing has a free tier and a Premium tier. The free plan allows 3 AI-generated presentations and 3 template downloads per month, with no access to the full template library. Premium is billed either monthly or annually (the annual plan is advertised as roughly 50% cheaper per month than the monthly plan); Slidesgo's pricing page is geo-localized and served this audit prices in Israeli shekels, so a reliable USD figure could not be confirmed — check the vendor's pricing page for the rate in your currency. A separate Teams plan offers custom, volume-based pricing for groups of 3 or more users, supporting organizations of up to 1,000 users.

Limitations: the free tier is quite restrictive at only 3 AI generations and 3 downloads per month. Even on Premium, generation and downloads are described as 'unlimited' but are capped at 150 per month as an anti-abuse measure. Some previously advertised capabilities, such as Canva editing integration and automatic brand-color customization or animated templates, could not be confirmed on Slidesgo's current pricing or AI Presentation Maker pages and should not be assumed. Template-based output can also look similar across different Slidesgo users.

Best suited for students, educators, small business owners, and individuals who need professional-looking presentations quickly and work primarily in Google Slides or PowerPoint, and who can work within the free tier's tight monthly limits or are willing to pay for Premium.$x$
 WHERE slug = 'slidesgo' AND lang = 'en';

UPDATE tools SET pros = ARRAY[$x$30,000+ templates covering most common presentation use cases$x$, $x$AI generation creates a complete deck from a single topic description$x$, $x$Works natively in Google Slides and PowerPoint — no new tool to learn$x$, $x$Teams plan offers custom volume pricing for organizations up to 1,000 users$x$, $x$Free tier lets users try AI generation and template downloads before paying$x$]::text[]
 WHERE slug = 'slidesgo' AND lang = 'en';

UPDATE tools SET cons = ARRAY[$x$Free tier is very limited: only 3 AI-generated presentations and 3 template downloads per month$x$, $x$Full 30,000+ template library requires a paid Premium subscription$x$, $x$Premium's 'unlimited' generations and downloads are actually capped at 150 per month$x$, $x$Premium pricing is geo-localized and not clearly published in USD$x$, $x$Template-based output can be recognizable to audiences familiar with Slidesgo$x$]::text[]
 WHERE slug = 'slidesgo' AND lang = 'en';

UPDATE tools SET choose_if = $x$["✅ You want professionally designed PowerPoint or Google Slides templates with beautiful layouts", "✅ You need presentations that work in traditional formats your audience expects", "✅ You want a large library of templates for specific industries, occasions, and topics", "✅ You prefer to start from a designed template and customize it rather than AI-generating everything"]$x$::jsonb
 WHERE slug = 'slidesgo' AND lang = 'en';

UPDATE tools SET faq = $x$[{"q": "What is Slidesgo?", "a": "Slidesgo is a library of presentation templates for Google Slides and PowerPoint, offering a limited free tier and paid Premium plans. It provides thousands of professionally designed templates for business, education, marketing, and creative purposes. Slidesgo AI can generate a presentation from a text prompt as a complete slide file."}, {"q": "Is Slidesgo free?", "a": "There is a free plan, but it is limited to 3 AI-generated presentations and 3 template downloads per month, with no access to the full template library. Premium removes those limits (up to a 150/month cap on generations and downloads), unlocks the full 30,000+ library, and adds features like Slidesclass lessons and early access to new AI features. Premium is billed monthly or annually, with pricing that varies by region — check Slidesgo's pricing page for the current rate in your currency. A separate custom-priced Teams plan is available for groups of 3 or more users."}, {"q": "What is the difference between Slidesgo and Canva?", "a": "Both offer presentation templates, but Slidesgo specializes in presentation templates for Google Slides and PowerPoint. Canva is a broader design platform with presentations as one of many format types. Slidesgo has more presentation-specific templates; Canva has more overall design versatility."}]$x$::jsonb
 WHERE slug = 'slidesgo' AND lang = 'en';

UPDATE tools SET best_for = $x$Plantillas de presentaciones generadas por IA para Google Slides y PowerPoint, con un nivel gratuito limitado y planes Premium de pago$x$
 WHERE slug = 'slidesgo' AND lang = 'es';

UPDATE tools SET description = $x$Slidesgo es una plataforma de plantillas de presentaciones con inteligencia artificial que cuenta con más de 30.000 plantillas para Google Slides y PowerPoint. El nivel gratuito incluye 3 presentaciones generadas por IA y 3 descargas de plantillas al mes; Premium desbloquea la biblioteca completa, con precios que varían según la región y el ciclo de facturación.$x$
 WHERE slug = 'slidesgo' AND lang = 'es';

UPDATE tools SET description_long = $x$Slidesgo es una plataforma de plantillas de presentaciones con capacidades de generación mediante IA, que ofrece más de 30.000 plantillas diseñadas profesionalmente para Google Slides y PowerPoint. Aproximadamente 15.000 de esas plantillas son exclusivas del nivel Premium de pago.

El producto se mantiene activamente; el proveedor no publica un número de versión ni revela qué modelo de IA impulsa su función de generación, por lo que ninguno de los dos datos puede confirmarse aquí. No se encontró en las páginas propias de Slidesgo ninguna cifra de número de usuarios verificada de forma independiente.

Slidesgo AI genera un mazo de presentación completo a partir de la descripción de un tema, seleccionando plantillas y generando el contenido de las diapositivas. La biblioteca abarca la mayoría de los casos de uso comunes —informes empresariales, presentaciones educativas, mazos de marketing, propuestas de proyectos, anuncios de eventos— y, según se informa, se añaden nuevas plantillas de forma regular.

Los precios cuentan con un nivel gratuito y un nivel Premium. El plan gratuito permite 3 presentaciones generadas por IA y 3 descargas de plantillas al mes, sin acceso a la biblioteca completa de plantillas. Premium se factura mensual o anualmente (el plan anual se anuncia como aproximadamente un 50 % más barato por mes que el plan mensual); la página de precios de Slidesgo está geolocalizada y, durante esta auditoría, mostró los precios en séqueles israelíes, por lo que no se pudo confirmar una cifra fiable en dólares estadounidenses: consulte la página de precios del proveedor para conocer la tarifa en su moneda. Existe un plan Teams independiente con precios personalizados según el volumen para grupos de 3 o más usuarios, que admite organizaciones de hasta 1.000 usuarios.

Limitaciones: el nivel gratuito es bastante restrictivo, con solo 3 generaciones por IA y 3 descargas al mes. Incluso en Premium, la generación y las descargas se describen como "ilimitadas", pero están limitadas a 150 al mes como medida contra el abuso. Algunas funciones anunciadas anteriormente, como la integración de edición con Canva y la personalización automática de colores de marca o plantillas animadas, no pudieron confirmarse en las páginas actuales de precios o del Generador de Presentaciones con IA de Slidesgo, por lo que no deben darse por supuestas. El resultado basado en plantillas también puede verse similar entre distintos usuarios de Slidesgo.

Más adecuado para estudiantes, educadores, pequeños empresarios y personas que necesitan presentaciones con aspecto profesional de forma rápida y que trabajan principalmente en Google Slides o PowerPoint, y que pueden adaptarse a los límites mensuales ajustados del nivel gratuito o están dispuestos a pagar por Premium.$x$
 WHERE slug = 'slidesgo' AND lang = 'es';

