 WHERE slug = 'slidesgo' AND lang = 'es';

UPDATE tools SET cons = ARRAY[$x$El nivel gratuito es muy limitado: solo 3 presentaciones generadas por IA y 3 descargas de plantillas al mes$x$, $x$La biblioteca completa de más de 30.000 plantillas requiere una suscripción Premium de pago$x$, $x$Las generaciones y descargas "ilimitadas" de Premium en realidad están limitadas a 150 al mes$x$, $x$El precio de Premium está geolocalizado y no se publica claramente en dólares estadounidenses$x$, $x$El resultado basado en plantillas puede resultar reconocible para audiencias familiarizadas con Slidesgo$x$]::text[]
