 WHERE slug = 'udio' AND lang = 'en';

UPDATE tools SET faq = $x$[{"q": "Is Suno or Udio better?", "a": "Suno is better for quickly generating complete songs — it's faster and more user-friendly. Udio generally produces higher sonic quality but currently disables downloads of generated tracks for all users. Both are competitive; Suno leads on ease of use and community size."}, {"q": "Is Suno free?", "a": "Suno offers a free plan with 50 credits per day (about 10 songs). The Pro plan is $8/month and Premier is $24/month for more credits, commercial use rights, and priority generation."}, {"q": "Can I sell music made with Suno?", "a": "Yes, on paid plans. Suno Pro and Premier grant commercial use rights to generated music. The free plan does not allow commercial use. Always check current terms as AI music licensing continues to evolve."}, {"q": "What is Udio AI?", "a": "Udio is an AI music generation tool that creates songs from text prompts. It launched in 2024 and is known for particularly high sonic quality. Udio has faced legal challenges from major record labels over training data."}]$x$::jsonb
