UPDATE tools SET faq = $x$[{"q": "Ist Suno oder Udio besser?", "a": "Suno eignet sich besser, um schnell vollständige Songs zu erstellen – es ist schneller und benutzerfreundlicher. Udio erzielt in der Regel höhere Klangqualität, deaktiviert aber derzeit für alle Nutzer den Download generierter Tracks. Beide sind konkurrenzfähig; Suno führt bei Benutzerfreundlichkeit und Community-Größe."}, {"q": "Ist Suno kostenlos?", "a": "Suno bietet einen kostenlosen Tarif mit 50 Credits pro Tag (etwa 10 Songs). Der Pro-Tarif kostet 8 $/Monat und Premier 24 $/Monat für mehr Credits, kommerzielle Nutzungsrechte und bevorzugte Generierung."}, {"q": "Kann ich mit Suno erstellte Musik verkaufen?", "a": "Ja, bei bezahlten Tarifen. Suno Pro und Premier räumen kommerzielle Nutzungsrechte für generierte Musik ein. Der kostenlose Tarif erlaubt keine kommerzielle Nutzung. Prüfen Sie stets die aktuellen Bedingungen, da sich die Lizenzierung von KI-Musik weiterentwickelt."}, {"q": "Was ist Udio AI?", "a": "Udio ist ein KI-Musikgenerierungstool, das Songs aus Textprompts erstellt. Es wurde 2024 eingeführt und ist besonders für seine hohe Klangqualität bekannt. Udio sah sich rechtlichen Herausforderungen großer Plattenlabels wegen der Trainingsdaten ausgesetzt."}]$x$::jsonb
 WHERE slug = 'udio' AND lang = 'de';

