 WHERE slug = 'zed' AND lang = 'en';

UPDATE tools SET faq = $x$[{"q": "What is Zed?", "a": "Zed is a high-performance code editor built in Rust by the creators of Atom and Tree-sitter. It's extremely fast due to its native architecture (no Electron), supports real-time multiplayer collaboration, and includes built-in AI assistance using models from providers such as Anthropic, OpenAI, and Google."}, {"q": "Is Zed free?", "a": "Zed's editor is free to use, and the Personal plan gives you Zed-hosted AI up to 2,000 accepted edit predictions at no cost, or unlimited use if you bring your own API keys. Beyond that, the Pro plan costs $10 per month for unlimited edit predictions plus $5 in monthly AI tokens, and a Business plan is available for teams."}, {"q": "Is Zed faster than VS Code?", "a": "Yes. Zed is significantly faster than VS Code and Cursor (which are Electron-based) because it's built in Rust with GPU-accelerated rendering. Startup times, file loading, and editing feel noticeably snappier, especially on large codebases."}, {"q": "Does Zed have GitHub Copilot support?", "a": "Zed has its own built-in AI integration using models from providers including Anthropic, OpenAI, and Google. GitHub Copilot extension support is limited — Zed doesn't have the same rich extension ecosystem as VS Code. If you rely on specific VS Code extensions, Cursor is a safer choice."}]$x$::jsonb
 WHERE slug = 'zed' AND lang = 'en';

